use csv::{ReaderBuilder, Trim};
use fancy_regex::{Captures, Regex as FancyRegex};
use indexmap::IndexMap;
use itertools::Itertools;
use nu_engine::command_prelude::*;
use nu_protocol::{Config, ListStream, Range, Signals};
use regex::Regex;
use std::collections::VecDeque;
use std::io::Cursor;
use std::iter::Peekable;
use std::str::CharIndices;
use std::sync::Arc;
use unicode_segmentation::UnicodeSegmentation;

use crate::grapheme_flags;
use crate::grapheme_flags_const;

type DetectInput<'t> = Peekable<CharIndices<'t>>;

#[derive(Clone)]
pub struct SubCommand {
    column_separator: String,
    column_separator_span: Span,
    column_names: Vec<String>,
    collapse_empty: bool,
    column_has_regex: bool,
    column_head: Span,
    row_separator: String,
    row_separator_span: Span,
    row_max_split: Option<usize>,
    row_has_regex: bool,
    row_head: Span,
    list_separator: Value,
    list_has_regex: bool,
    list_head: Span,
    min_word_length: Option<usize>,
    words_graphemes: bool,
    words_has_grapheme_flag: bool,
    words_has_utf8_flag: bool,
    words_head: Span,
    parse_pattern: String,
    parse_pattern_span: Span,
    parse_regex_mode: bool,
    parse_head: Span,
    table_head: Span,
    table_no_headers: bool,
    detect_skip: Option<usize>,
    detect_combine: Option<Range>,
    detect_guess: bool,
    detect_config: Arc<Config>,
    delimited_separator: char,
    delimited_comment: Option<char>,
    delimited_quote: char,
    delimited_escape: Option<char>,
    delimited_flexible: bool,
    delimited_no_infer: bool,
    delimited_trim: Trim,
    ssv_aligned: bool,
    ssv_split_at: usize,
}

impl Default for SubCommand {
    fn default() -> Self {
        Self {
            column_separator: String::new(),
            column_separator_span: Span::unknown(),
            column_names: Vec::new(),
            collapse_empty: false,
            column_has_regex: false,
            column_head: Span::unknown(),
            row_separator: String::new(),
            row_separator_span: Span::unknown(),
            row_max_split: None,
            row_has_regex: false,
            row_head: Span::unknown(),
            list_separator: Value::nothing(Span::unknown()),
            list_has_regex: false,
            list_head: Span::unknown(),
            min_word_length: None,
            words_graphemes: false,
            words_has_grapheme_flag: false,
            words_has_utf8_flag: false,
            words_head: Span::unknown(),
            parse_pattern: String::new(),
            parse_pattern_span: Span::unknown(),
            parse_regex_mode: false,
            parse_head: Span::unknown(),
            table_head: Span::unknown(),
            table_no_headers: false,
            detect_skip: None,
            detect_combine: None,
            detect_guess: false,
            detect_config: Arc::new(Config::default()),
            delimited_separator: ',',
            delimited_comment: None,
            delimited_quote: '"',
            delimited_escape: None,
            delimited_flexible: false,
            delimited_no_infer: false,
            delimited_trim: Trim::None,
            ssv_aligned: false,
            ssv_split_at: 2,
        }
    }
}

impl Command for SubCommand {
    fn name(&self) -> &str {
        "split column"
    }

    fn signature(&self) -> Signature {
        Signature::build("split column")
            .input_output_types(vec![
                (Type::String, Type::table()),
                (
                    // TODO: no test coverage (is this behavior a bug or a feature?)
                    Type::List(Box::new(Type::String)),
                    Type::table(),
                ),
            ])
            .required(
                "separator",
                SyntaxShape::String,
                "The character or string that denotes what separates columns.",
            )
            .switch("collapse-empty", "remove empty columns", Some('c'))
            .switch("regex", "separator is a regular expression", Some('r'))
            .rest(
                "rest",
                SyntaxShape::String,
                "Column names to give the new columns.",
            )
            .category(Category::Strings)
    }

    fn description(&self) -> &str {
        "Split a string into multiple columns using a separator."
    }

    fn search_terms(&self) -> Vec<&str> {
        vec!["separate", "divide", "regex"]
    }

    fn examples(&self) -> Vec<Example> {
        vec![
            Example {
                description: "Split a string into columns by the specified separator",
                example: "'a--b--c' | split column '--'",
                result: Some(Value::test_list(vec![Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                        "column3" => Value::test_string("c"),
                })])),
            },
            Example {
                description: "Split a string into columns of char and remove the empty columns",
                example: "'abc' | split column --collapse-empty ''",
                result: Some(Value::test_list(vec![Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                        "column3" => Value::test_string("c"),
                })])),
            },
            Example {
                description: "Split a list of strings into a table",
                example: "['a-b' 'c-d'] | split column -",
                result: Some(Value::test_list(vec![
                    Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                    }),
                    Value::test_record(record! {
                        "column1" => Value::test_string("c"),
                        "column2" => Value::test_string("d"),
                    }),
                ])),
            },
            Example {
                description: "Split a list of strings into a table, ignoring padding",
                example: r"['a -  b' 'c  -    d'] | split column --regex '\s*-\s*'",
                result: Some(Value::test_list(vec![
                    Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                    }),
                    Value::test_record(record! {
                        "column1" => Value::test_string("c"),
                        "column2" => Value::test_string("d"),
                    }),
                ])),
            },
        ]
    }

    fn is_const(&self) -> bool {
        true
    }

    fn run(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let separator: Spanned<String> = call.req(engine_state, stack, 0)?;
        let rest: Vec<Spanned<String>> = call.rest(engine_state, stack, 1)?;
        let collapse_empty = call.has_flag(engine_state, stack, "collapse-empty")?;
        let has_regex = call.has_flag(engine_state, stack, "regex")?;

        let worker = SubCommand {
            column_separator: separator.item,
            column_separator_span: separator.span,
            column_names: rest.into_iter().map(|s| s.item).collect(),
            collapse_empty,
            column_has_regex: has_regex,
            column_head: call.head,
            ..SubCommand::default()
        };
        worker.split_column_pipeline(engine_state, input)
    }

    fn run_const(
        &self,
        working_set: &StateWorkingSet,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let separator: Spanned<String> = call.req_const(working_set, 0)?;
        let rest: Vec<Spanned<String>> = call.rest_const(working_set, 1)?;
        let collapse_empty = call.has_flag_const(working_set, "collapse-empty")?;
        let has_regex = call.has_flag_const(working_set, "regex")?;

        let worker = SubCommand {
            column_separator: separator.item,
            column_separator_span: separator.span,
            column_names: rest.into_iter().map(|s| s.item).collect(),
            collapse_empty,
            column_has_regex: has_regex,
            column_head: call.head,
            ..SubCommand::default()
        };
        worker.split_column_pipeline(working_set.permanent(), input)
    }
}

impl SubCommand {
    fn compile_column_regex(&self) -> Result<Regex, ShellError> {
        let compiled = if self.column_has_regex {
            Regex::new(&self.column_separator)
        } else {
            Regex::new(&regex::escape(&self.column_separator))
        };
        compiled.map_err(|e| ShellError::GenericError {
            error: "Error with regular expression".into(),
            msg: e.to_string(),
            span: Some(self.column_separator_span),
            help: None,
            inner: vec![],
        })
    }

    fn split_column_pipeline(
        &self,
        engine_state: &EngineState,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let regex = self.compile_column_regex()?;
        let worker = SubCommand {
            column_separator: self.column_separator.clone(),
            column_separator_span: self.column_separator_span,
            column_names: self.column_names.clone(),
            collapse_empty: self.collapse_empty,
            column_has_regex: self.column_has_regex,
            column_head: self.column_head,
            ..SubCommand::default()
        };
        input.flat_map(
            move |value| worker.split_column_value(&value, &regex),
            engine_state.signals(),
        )
    }

    fn split_column_value(&self, v: &Value, separator: &Regex) -> Vec<Value> {
        if let Ok(s) = v.coerce_str() {
            let split_result = self.collect_column_parts(separator, &s);
            if self.collapse_empty && split_result.is_empty() && self.column_names.is_empty() {
                return vec![Value::record(Record::new(), self.column_head)];
            }
            vec![self.record_from_column_parts(&split_result)]
        } else {
            vec![self.column_value_error(v)]
        }
    }

    fn collect_column_parts<'a>(&self, separator: &'a Regex, s: &'a str) -> Vec<&'a str> {
        separator
            .split(s)
            .filter(|x| !(self.collapse_empty && x.is_empty()))
            .collect()
    }

    fn generated_column_names(&self, count: usize) -> Vec<String> {
        if self.column_names.is_empty() {
            (0..count).map(|i| format!("column{}", i + 1)).collect()
        } else {
            self.column_names.clone()
        }
    }

    fn record_from_column_parts(&self, split_result: &[&str]) -> Value {
        let names = self.generated_column_names(split_result.len());
        let mut record = Record::new();
        if self.column_names.is_empty() {
            for (&part, name) in split_result.iter().zip(&names) {
                record.push(name, Value::string(part, self.column_head));
            }
        } else {
            for (&part, name) in split_result.iter().zip(&self.column_names) {
                record.push(name, Value::string(part, self.column_head));
            }
        }
        Value::record(record, self.column_head)
    }

    fn column_value_error(&self, v: &Value) -> Value {
        match v {
            Value::Error { error, .. } => Value::error(*error.clone(), self.column_head),
            v => {
                let span = v.span();
                Value::error(
                    ShellError::PipelineMismatch {
                        exp_input_type: "string".into(),
                        dst_span: self.column_head,
                        src_span: span,
                    },
                    span,
                )
            }
        }
    }

    pub(crate) fn run_split_row(
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let separator: Spanned<String> = call.req(engine_state, stack, 0)?;
        let max_split: Option<usize> = call.get_flag(engine_state, stack, "number")?;
        let has_regex = call.has_flag(engine_state, stack, "regex")?;
        let worker = SubCommand {
            row_separator: separator.item,
            row_separator_span: separator.span,
            row_max_split: max_split,
            row_has_regex: has_regex,
            row_head: call.head,
            ..SubCommand::default()
        };
        worker.split_row_pipeline(engine_state, input)
    }

    pub(crate) fn run_split_row_const(
        working_set: &StateWorkingSet,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let separator: Spanned<String> = call.req_const(working_set, 0)?;
        let max_split: Option<usize> = call.get_flag_const(working_set, "number")?;
        let has_regex = call.has_flag_const(working_set, "regex")?;
        let worker = SubCommand {
            row_separator: separator.item,
            row_separator_span: separator.span,
            row_max_split: max_split,
            row_has_regex: has_regex,
            row_head: call.head,
            ..SubCommand::default()
        };
        worker.split_row_pipeline(working_set.permanent(), input)
    }

    fn compile_row_regex(&self) -> Result<Regex, ShellError> {
        let compiled = if self.row_has_regex {
            Regex::new(&self.row_separator)
        } else {
            Regex::new(&regex::escape(&self.row_separator))
        };
        compiled.map_err(|e| {
self.row_separator_error(e.to_string())
        })
    }

    fn row_separator_error(&self, message: impl Into<String>) -> ShellError {
        ShellError::GenericError {
            error: "Error with regular expression".into(),
            msg: message.into(),
            span: Some(self.row_separator_span),
            help: None,
            inner: vec![],
        }
    }

    fn split_row_pipeline(
        &self,
        engine_state: &EngineState,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let regex = self.compile_row_regex()?;
        let worker = SubCommand {
            row_separator: self.row_separator.clone(),
            row_separator_span: self.row_separator_span,
            row_max_split: self.row_max_split,
            row_has_regex: self.row_has_regex,
            row_head: self.row_head,
            ..SubCommand::default()
        };
        input.flat_map(
            move |value| worker.split_row_value(&value, &regex),
            engine_state.signals(),
        )
    }

    fn split_row_value(&self, v: &Value, regex: &Regex) -> Vec<Value> {
        let span = v.span();
        match v {
            Value::Error { error, .. } => vec![Value::error(*error.clone(), span)],
            v => {
                let v_span = v.span();
                if let Ok(s) = v.coerce_str() {
                    self.row_split_parts(regex, &s, v_span)
                } else {
                    vec![self.row_value_error(v_span)]
                }
            }
        }
    }

    fn row_split_parts(&self, regex: &Regex, s: &str, v_span: Span) -> Vec<Value> {
        match self.row_max_split {
            Some(max_split) => regex
                .splitn(s, max_split)
                .map(|x| Value::string(x, v_span))
                .collect(),
            None => regex
                .split(s)
                .map(|x| Value::string(x, v_span))
                .collect(),
        }
    }

    fn row_value_error(&self, src_span: Span) -> Value {
        Value::error(
            ShellError::PipelineMismatch {
                exp_input_type: "string".into(),
                dst_span: self.row_head,
                src_span,
            },
            self.row_head,
        )
    }

    pub(crate) fn run_split_list(
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let has_regex = call.has_flag(engine_state, stack, "regex")?;
        let separator: Value = call.req(engine_state, stack, 0)?;
        let worker = SubCommand {
            list_separator: separator,
            list_has_regex: has_regex,
            list_head: call.head,
            ..SubCommand::default()
        };
        worker.split_list_pipeline(engine_state, call, input)
    }

    pub(crate) fn run_split_list_const(
        working_set: &StateWorkingSet,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let has_regex = call.has_flag_const(working_set, "regex")?;
        let separator: Value = call.req_const(working_set, 0)?;
        let worker = SubCommand {
            list_separator: separator,
            list_has_regex: has_regex,
            list_head: call.head,
            ..SubCommand::default()
        };
        worker.split_list_pipeline(working_set.permanent(), call, input)
    }

    fn list_matcher_regex(&self) -> Result<Option<Regex>, ShellError> {
        if !self.list_has_regex {
            return Ok(None);
        }
        let lhs = self.list_separator.coerce_str()?;
        Regex::new(&lhs).map(Some).map_err(|e| ShellError::GenericError {
            error: "Error with regular expression".into(),
            msg: e.to_string(),
            span: match &self.list_separator {
                Value::Error { .. } => None,
                _ => Some(self.list_separator.span()),
            },
            help: None,
            inner: vec![],
        })
    }

    fn list_compare_value(&self, rhs: &Value, regex: Option<&Regex>) -> Result<bool, ShellError> {
        if self.list_has_regex {
            if let Some(regex) = regex {
                if let Ok(rhs_str) = rhs.coerce_str() {
                    Ok(regex.is_match(&rhs_str))
                } else {
                    Ok(false)
                }
            } else {
                Ok(false)
            }
        } else {
            Ok(rhs == &self.list_separator)
        }
    }

    fn split_list_pipeline(
        &self,
        engine_state: &EngineState,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let worker = SubCommand {
            list_separator: self.list_separator.clone(),
            list_has_regex: self.list_has_regex,
            list_head: self.list_head,
            ..SubCommand::default()
        };
        let regex = worker.list_matcher_regex()?;
        let mut temp_list = Vec::new();
        let mut returned_list = Vec::new();
        for val in input {
            engine_state.signals().check(call.head)?;
            if worker.list_compare_value(&val, regex.as_ref())? {
                worker.flush_list_chunk(&mut temp_list, &mut returned_list);
            } else {
                temp_list.push(val);
            }
        }
        worker.flush_list_chunk(&mut temp_list, &mut returned_list);
        Ok(Value::list(returned_list, worker.list_head).into_pipeline_data())
    }

    fn flush_list_chunk(&self, temp_list: &mut Vec<Value>, returned_list: &mut Vec<Value>) {
        if !temp_list.is_empty() {
            returned_list.push(Value::list(temp_list.clone(), self.list_head));
            temp_list.clear();
        }
    }


    pub(crate) fn run_split_words(
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let word_length: Option<usize> = call.get_flag(engine_state, stack, "min-word-length")?;
        let has_grapheme = call.has_flag(engine_state, stack, "grapheme-clusters")?;
        let has_utf8 = call.has_flag(engine_state, stack, "utf-8-bytes")?;
        let graphemes = grapheme_flags(engine_state, stack, call)?;
        let worker = SubCommand {
            min_word_length: word_length,
            words_graphemes: graphemes,
            words_has_grapheme_flag: has_grapheme,
            words_has_utf8_flag: has_utf8,
            words_head: call.head,
            ..SubCommand::default()
        };
        worker.split_words_pipeline(engine_state, input)
    }

    pub(crate) fn run_split_words_const(
        working_set: &StateWorkingSet,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let word_length: Option<usize> = call.get_flag_const(working_set, "min-word-length")?;
        let has_grapheme = call.has_flag_const(working_set, "grapheme-clusters")?;
        let has_utf8 = call.has_flag_const(working_set, "utf-8-bytes")?;
        let graphemes = grapheme_flags_const(working_set, call)?;
        let worker = SubCommand {
            min_word_length: word_length,
            words_graphemes: graphemes,
            words_has_grapheme_flag: has_grapheme,
            words_has_utf8_flag: has_utf8,
            words_head: call.head,
            ..SubCommand::default()
        };
        worker.split_words_pipeline(working_set.permanent(), input)
    }

    fn validate_word_flags(&self) -> Result<(), ShellError> {
        if self.min_word_length.is_none() {
            if self.words_has_grapheme_flag {
                return Err(ShellError::IncompatibleParametersSingle {
                    msg: "--grapheme-clusters (-g) requires --min-word-length (-l)".to_string(),
                    span: self.words_head,
                });
            }
            if self.words_has_utf8_flag {
                return Err(ShellError::IncompatibleParametersSingle {
                    msg: "--utf-8-bytes (-b) requires --min-word-length (-l)".to_string(),
                    span: self.words_head,
                });
            }
        }
        Ok(())
    }

    fn split_words_pipeline(
        &self,
        engine_state: &EngineState,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        self.validate_word_flags()?;
        let worker = SubCommand {
            min_word_length: self.min_word_length,
            words_graphemes: self.words_graphemes,
            words_has_grapheme_flag: self.words_has_grapheme_flag,
            words_has_utf8_flag: self.words_has_utf8_flag,
            words_head: self.words_head,
            ..SubCommand::default()
        };
        input.map(
            move |x| worker.split_words_value(&x),
            engine_state.signals(),
        )
    }

    fn split_words_value(&self, v: &Value) -> Value {
        let v_span = v.span();
        match v {
            Value::Error { error, .. } => Value::error(*error.clone(), v_span),
            v => {
                let v_span = v.span();
                if let Ok(s) = v.coerce_str() {
                    if self.min_word_length == Some(0) && self.words_graphemes {
                        return Value::list(self.collect_words(&s, v_span), v_span);
                    }
                    Value::list(self.collect_words(&s, v_span), v_span)
                } else {
                    self.words_value_error(v_span)
                }
            }
        }
    }

    fn collect_words(&self, s: &str, v_span: Span) -> Vec<Value> {
        let regex_replace = FancyRegex::new(r"[^\p{L}\p{N}']").expect("regular expression error");
        let replaced_string = regex_replace.replace_all(s, " ").to_string();
        replaced_string
            .split(' ')
            .filter_map(|part| {
                if part.trim().is_empty() {
                    None
                } else if self.word_length_ok(part) {
                    Some(Value::string(part, v_span))
                } else {
                    None
                }
            })
            .collect()
    }

    fn word_length_ok(&self, s: &str) -> bool {
        match self.min_word_length {
            Some(len) => {
                let measured = if self.words_graphemes {
                    s.graphemes(true).count()
                } else {
                    s.len()
                };
                measured >= len
            }
            None => true,
        }
    }

    fn words_value_error(&self, src_span: Span) -> Value {
        Value::error(
            ShellError::PipelineMismatch {
                exp_input_type: "string".into(),
                dst_span: self.words_head,
                src_span,
            },
            src_span,
        )
    }

    pub(crate) fn run_parse(
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let pattern: Spanned<String> = call.req(engine_state, stack, 0)?;
        let regex = call.has_flag(engine_state, stack, "regex")?;
        let worker = SubCommand {
            parse_pattern: pattern.item,
            parse_pattern_span: pattern.span,
            parse_regex_mode: regex,
            parse_head: call.head,
            ..SubCommand::default()
        };
        worker.parse_pipeline(engine_state, input)
    }

    pub(crate) fn run_parse_const(
        working_set: &StateWorkingSet,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let pattern: Spanned<String> = call.req_const(working_set, 0)?;
        let regex = call.has_flag_const(working_set, "regex")?;
        let worker = SubCommand {
            parse_pattern: pattern.item,
            parse_pattern_span: pattern.span,
            parse_regex_mode: regex,
            parse_head: call.head,
            ..SubCommand::default()
        };
        worker.parse_pipeline(working_set.permanent(), input)
    }

    fn compile_parse_regex(&self) -> Result<FancyRegex, ShellError> {
        let item_to_parse = if self.parse_regex_mode {
            self.parse_pattern.clone()
        } else {
            self.build_simple_parse_pattern()?
        };
        FancyRegex::new(&item_to_parse).map_err(|e| ShellError::GenericError {
            error: "Error with regular expression".into(),
            msg: e.to_string(),
            span: Some(self.parse_pattern_span),
            help: None,
            inner: vec![],
        })
    }

    fn build_simple_parse_pattern(&self) -> Result<String, ShellError> {
        let mut output = "(?s)\\A".to_string();
        let mut loop_input = self.parse_pattern.chars().peekable();
        loop {
            let mut before = String::new();
            while let Some(c) = loop_input.next() {
                if c == '{' {
                    if loop_input.peek() == Some(&'{') {
                        let _ = loop_input.next();
                    } else {
                        break;
                    }
                }
                before.push(c);
            }

            if !before.is_empty() {
                output.push_str(&fancy_regex::escape(&before));
            }

            let mut column = String::new();
            while let Some(c) = loop_input.next() {
                if c == '}' {
                    break;
                }
                column.push(c);
                if loop_input.peek().is_none() {
                    return Err(ShellError::DelimiterError {
                        msg: "Found opening `{` without an associated closing `}`".to_owned(),
                        span: self.parse_pattern_span,
                    });
                }
            }

            if !column.is_empty() {
                output.push_str("(?P<");
                output.push_str(&column);
                output.push_str(">.*?)");
            }

            if before.is_empty() && column.is_empty() {
                break;
            }
        }

        output.push_str("\\z");
        Ok(output)
    }

    fn parse_capture_columns(&self, regex: &FancyRegex) -> Vec<String> {
        regex
            .capture_names()
            .skip(1)
            .enumerate()
            .map(|(i, name)| {
                name.map(String::from)
                    .unwrap_or_else(|| format!("capture{i}"))
            })
            .collect()
    }

    fn parse_pipeline(
        &self,
        engine_state: &EngineState,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let worker = SubCommand {
            parse_pattern: self.parse_pattern.clone(),
            parse_pattern_span: self.parse_pattern_span,
            parse_regex_mode: self.parse_regex_mode,
            parse_head: self.parse_head,
            ..SubCommand::default()
        };
        let regex = worker.compile_parse_regex()?;
        let columns = worker.parse_capture_columns(&regex);
        let head = worker.parse_head;
        match input {
            PipelineData::Empty => Ok(PipelineData::Empty),
            PipelineData::Value(value, ..) => match value {
                Value::String { val, .. } => {
                    let captures = regex
                        .captures_iter(&val)
                        .map(|captures| worker.parse_capture_record(captures, &columns))
                        .collect::<Result<_, _>>()?;
                    Ok(Value::list(captures, head).into_pipeline_data())
                }
                Value::List { vals, .. } => {
                    let iter = vals.into_iter().map(move |val| {
                        let span = val.span();
                        val.into_string().map_err(|_| ShellError::PipelineMismatch {
                            exp_input_type: "string".into(),
                            dst_span: head,
                            src_span: span,
                        })
                    });
                    let iter = ParseIter {
                        captures: VecDeque::new(),
                        regex,
                        columns,
                        iter,
                        span: head,
                        signals: engine_state.signals().clone(),
                    };
                    Ok(ListStream::new(iter, head, Signals::empty()).into())
                }
                value => Err(worker.parse_type_error(value.span())),
            },
            PipelineData::ListStream(stream, ..) => Ok(stream
                .modify(|stream| {
                    let iter = stream.map(move |val| {
                        let span = val.span();
                        val.into_string().map_err(|_| ShellError::PipelineMismatch {
                            exp_input_type: "string".into(),
                            dst_span: head,
                            src_span: span,
                        })
                    });
                    ParseIter {
                        captures: VecDeque::new(),
                        regex,
                        columns,
                        iter,
                        span: head,
                        signals: engine_state.signals().clone(),
                    }
                })
                .into()),
            PipelineData::ByteStream(stream, ..) => {
                if let Some(lines) = stream.lines() {
                    let iter = ParseIter {
                        captures: VecDeque::new(),
                        regex,
                        columns,
                        iter: lines,
                        span: head,
                        signals: engine_state.signals().clone(),
                    };
                    Ok(ListStream::new(iter, head, Signals::empty()).into())
                } else {
                    Ok(PipelineData::Empty)
                }
            }
        }
    }

    fn parse_type_error(&self, src_span: Span) -> ShellError {
        ShellError::PipelineMismatch {
            exp_input_type: "string".into(),
            dst_span: self.parse_head,
            src_span,
        }
    }

    fn parse_capture_record(
        &self,
        captures: Result<Captures, fancy_regex::Error>,
        columns: &[String],
    ) -> Result<Value, ShellError> {
        let captures = captures.map_err(|err| ShellError::GenericError {
            error: "Error with regular expression captures".into(),
            msg: err.to_string(),
            span: Some(self.parse_head),
            help: None,
            inner: vec![],
        })?;
        let record = columns
            .iter()
            .zip(captures.iter().skip(1))
            .map(|(column, match_)| {
                let match_str = match_.map(|m| m.as_str()).unwrap_or("");
                (column.clone(), Value::string(match_str, self.parse_head))
            })
            .collect();
        Ok(Value::record(record, self.parse_head))
    }

    pub(crate) fn run_detect_columns(
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let num_rows_to_skip: Option<usize> = call.get_flag(engine_state, stack, "skip")?;
        let noheader = call.has_flag(engine_state, stack, "no-headers")?;
        let range: Option<Range> = call.get_flag(engine_state, stack, "combine-columns")?;
        let guess = call.has_flag(engine_state, stack, "guess")?;
        let config = stack.get_config(engine_state);
        let worker = SubCommand {
            table_head: call.head,
            table_no_headers: noheader,
            detect_skip: num_rows_to_skip,
            detect_combine: range,
            detect_guess: guess,
            detect_config: config,
            ..SubCommand::default()
        };
        worker.detect_pipeline(engine_state, input)
    }

    pub(crate) fn run_detect_columns_const(
        working_set: &StateWorkingSet,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let num_rows_to_skip: Option<usize> = call.get_flag_const(working_set, "skip")?;
        let noheader = call.has_flag_const(working_set, "no-headers")?;
        let range: Option<Range> = call.get_flag_const(working_set, "combine-columns")?;
        let guess = call.has_flag_const(working_set, "guess")?;
        let config = working_set.get_config().clone();
        let worker = SubCommand {
            table_head: call.head,
            table_no_headers: noheader,
            detect_skip: num_rows_to_skip,
            detect_combine: range,
            detect_guess: guess,
            detect_config: config,
            ..SubCommand::default()
        };
        worker.detect_pipeline(working_set.permanent(), input)
    }

    fn detect_pipeline(
        &self,
        engine_state: &EngineState,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let worker = SubCommand {
            table_head: self.table_head,
            table_no_headers: self.table_no_headers,
            detect_skip: self.detect_skip,
            detect_combine: self.detect_combine.clone(),
            detect_guess: self.detect_guess,
            detect_config: Arc::clone(&self.detect_config),
            ..SubCommand::default()
        };
        if worker.detect_guess {
            worker.detect_guess_table(engine_state, input)
        } else {
            worker.detect_aligned_table(engine_state, input)
        }
    }

    fn detect_collect_input(&self, input: PipelineData) -> Result<String, ShellError> {
        let mut collected = input.collect_string("", &self.detect_config)?;
        if let Some(rows) = self.detect_skip {
            collected = collected.lines().skip(rows).map(|x| x.to_string()).join("\n");
        }
        Ok(collected)
    }

    fn detect_guess_table(
        &self,
        engine_state: &EngineState,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        use super::super::guess_width::GuessWidth;
        let input_span = input.span().unwrap_or(self.table_head);
        let collected = self.detect_collect_input(input)?;
        let mut guess_width = GuessWidth::new_reader(Box::new(Cursor::new(collected)));
        let result = guess_width.read_all();
        if result.is_empty() {
            return Ok(Value::nothing(input_span).into_pipeline_data());
        }
        let worker = self.clone();
        if !self.table_no_headers {
            let columns = result[0].clone();
            Ok(result
                .into_iter()
                .skip(1)
                .map(move |s| worker.detect_record_from_row(columns.clone(), s, input_span))
                .into_pipeline_data(input_span, engine_state.signals().clone()))
        } else {
            let length = result[0].len();
            let columns: Vec<String> = (0..length).map(|n| format!("column{n}")).collect();
            Ok(result
                .into_iter()
                .map(move |s| worker.detect_record_from_row(columns.clone(), s, input_span))
                .into_pipeline_data(input_span, engine_state.signals().clone()))
        }
    }

    fn detect_record_from_row(&self, columns: Vec<String>, s: Vec<String>, input_span: Span) -> Value {
        let span = if input_span == Span::unknown() {
            self.table_head
        } else {
            input_span
        };
        let mut values: Vec<Value> = s
            .into_iter()
            .map(|v| Value::string(v, span))
            .collect();
        for _ in values.len()..columns.len() {
            values.push(Value::string("", span));
        }
        let record = Record::from_raw_cols_vals(columns, values, span, span);
        match record {
            Ok(r) => self.merge_detect_record(r, span),
            Err(e) => Value::error(e, span),
        }
    }

    fn detect_aligned_table(
        &self,
        engine_state: &EngineState,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let name_span = self.table_head;
        let input = input.collect_string("", &self.detect_config)?;
        let input: Vec<_> = input
            .lines()
            .skip(self.detect_skip.unwrap_or_default())
            .map(|x| x.to_string())
            .collect();
        let mut input = input.into_iter();
        let headers = input.next();
        if let Some(orig_headers) = headers {
            let headers = self.detect_headers_from_line(&orig_headers);
            let worker = self.clone();
            Ok(self
                .table_no_headers
                .then_some(orig_headers)
                .into_iter()
                .chain(input)
                .map(move |x| worker.detect_row_record(&headers, &x, name_span))
                .into_pipeline_data(name_span, engine_state.signals().clone()))
        } else {
            Ok(PipelineData::empty())
        }
    }

    fn detect_headers_from_line(&self, orig_headers: &str) -> Vec<Spanned<String>> {
        let mut headers = find_detect_columns(orig_headers);
        if orig_headers.is_empty() && self.table_head == Span::unknown() {
            return headers;
        }
        if self.table_no_headers {
            for header in headers.iter_mut().enumerate() {
                header.1.item = format!("column{}", header.0);
            }
        }
        headers
    }

    fn detect_row_record(
        &self,
        headers: &[Spanned<String>],
        x: &str,
        name_span: Span,
    ) -> Value {
        let span = if name_span == Span::unknown() {
            self.table_head
        } else {
            name_span
        };
        let row = find_detect_columns(x);
        let mut record = Record::new();
        if headers.len() == row.len() {
            for (header, val) in headers.iter().zip(row.iter()) {
                record.push(&header.item, Value::string(&val.item, span));
            }
        } else {
            let pre_output = self.detect_fill_missing(headers, &row, span);
            for header in headers {
                for pre_o in &pre_output {
                    if pre_o.0 == header.item {
                        record.push(&header.item, pre_o.1.clone());
                    }
                }
            }
        }
        self.merge_detect_record(record, span)
    }

    fn detect_fill_missing(
        &self,
        headers: &[Spanned<String>],
        row: &[Spanned<String>],
        name_span: Span,
    ) -> Vec<(String, Value)> {
        let span = if name_span == Span::unknown() {
            self.table_head
        } else {
            name_span
        };
        let mut pre_output = vec![];
        for cell in row {
            for header in headers {
                if cell.span.start <= header.span.end && cell.span.end > header.span.start {
                    pre_output.push((header.item.to_string(), Value::string(&cell.item, span)));
                }
            }
        }
        for header in headers {
            let mut found = false;
            for pre_o in &pre_output {
                if pre_o.0 == header.item {
                    found = true;
                    break;
                }
            }
            if !found {
                pre_output.push((header.item.to_string(), Value::nothing(span)));
            }
        }
        pre_output
    }

    fn merge_detect_record(&self, record: Record, input_span: Span) -> Value {
        match &self.detect_combine {
            Some(range) => {
                let (start_index, end_index) = match self.process_detect_range(range, record.len(), input_span)
                {
                    Ok(Some((l_idx, r_idx))) => (l_idx, r_idx),
                    Ok(None) => return Value::record(record, input_span),
                    Err(e) => return Value::error(e, input_span),
                };
                match self.merge_detect_record_impl(record, start_index, end_index, input_span) {
                    Ok(rec) => Value::record(rec, input_span),
                    Err(err) => Value::error(err, input_span),
                }
            }
            None => {
                let span = if input_span == Span::unknown() {
                    self.table_head
                } else {
                    input_span
                };
                Value::record(record, span)
            }
        }
    }

    fn process_detect_range(
        &self,
        range: &Range,
        length: usize,
        input_span: Span,
    ) -> Result<Option<(usize, usize)>, ShellError> {
        match nu_cmd_base::util::process_range(range) {
            Ok((l_idx, r_idx)) => {
                let l_idx = if l_idx < 0 {
                    length as isize + l_idx
                } else {
                    l_idx
                };
                let r_idx = if r_idx < 0 {
                    length as isize + r_idx
                } else {
                    r_idx
                };
                if !(l_idx <= r_idx && (r_idx >= 0 || l_idx < (length as isize))) {
                    return Ok(None);
                }
                Ok(Some((
                    l_idx.max(0) as usize,
                    (r_idx as usize + 1).min(length),
                )))
            }
            Err(processing_error) => {
                let span = if input_span == Span::unknown() {
                    self.table_head
                } else {
                    input_span
                };
                Err(processing_error("could not find range index", span))
            }
        }
    }

    fn merge_detect_record_impl(
        &self,
        record: Record,
        start_index: usize,
        end_index: usize,
        input_span: Span,
    ) -> Result<Record, ShellError> {
        let (mut cols, mut vals): (Vec<_>, Vec<_>) = record.into_iter().unzip();
        ((start_index + 1)..(cols.len() - end_index + start_index + 1)).for_each(|idx| {
            cols.swap(idx, end_index - start_index - 1 + idx);
        });
        cols.truncate(cols.len() - end_index + start_index + 1);
        let combined = vals
            .iter()
            .take(end_index)
            .skip(start_index)
            .map(|v| v.coerce_str().unwrap_or_default())
            .join(" ");
        let binding = Value::string(combined, Span::unknown());
        let last_seg = vals.split_off(end_index);
        vals.truncate(start_index);
        vals.push(binding);
        vals.extend(last_seg);
        let span = if input_span == Span::unknown() {
            self.table_head
        } else {
            input_span
        };
        Record::from_raw_cols_vals(cols, vals, Span::unknown(), span)
    }

    pub(crate) fn from_delimited_config(
        separator: char,
        comment: Option<char>,
        quote: char,
        escape: Option<char>,
        noheaders: bool,
        flexible: bool,
        no_infer: bool,
        trim: Trim,
        name: Span,
    ) -> Self {
        SubCommand {
            table_head: name,
            table_no_headers: noheaders,
            delimited_separator: separator,
            delimited_comment: comment,
            delimited_quote: quote,
            delimited_escape: escape,
            delimited_flexible: flexible,
            delimited_no_infer: no_infer,
            delimited_trim: trim,
            ..SubCommand::default()
        }
    }

    pub(crate) fn delimited_pipeline(&self, input: PipelineData) -> Result<PipelineData, ShellError> {
        match input {
            PipelineData::Empty => Ok(PipelineData::Empty),
            PipelineData::Value(value, metadata) => {
                let string = value.into_string()?;
                let byte_stream = ByteStream::read_string(string, self.table_head, Signals::empty());
                Ok(PipelineData::ListStream(
                    self.delimited_from_bytes(byte_stream)?,
                    metadata,
                ))
            }
            PipelineData::ListStream(list_stream, _) => Err(ShellError::OnlySupportsThisInputType {
                exp_input_type: "string".into(),
                wrong_type: "list".into(),
                dst_span: self.table_head,
                src_span: list_stream.span(),
            }),
            PipelineData::ByteStream(byte_stream, metadata) => Ok(PipelineData::ListStream(
                self.delimited_from_bytes(byte_stream)?,
                metadata,
            )),
        }
    }

    fn delimited_from_bytes(&self, input: ByteStream) -> Result<ListStream, ShellError> {
        let input_reader = if let Some(stream) = input.reader() {
            stream
        } else {
            return Ok(ListStream::new(std::iter::empty(), self.table_head, Signals::empty()));
        };
        let mut reader = self.delimited_reader(input_reader);
        let headers = self.delimited_headers(&mut reader)?;
        let worker = self.clone();
        let iter = reader.into_records().map(move |row| worker.delimited_row_value(row, &headers));
        Ok(ListStream::new(iter, self.table_head, Signals::empty()))
    }

    fn delimited_reader<R: std::io::Read>(&self, input_reader: R) -> csv::Reader<R> {
        ReaderBuilder::new()
            .has_headers(!self.table_no_headers)
            .flexible(self.delimited_flexible)
            .delimiter(self.delimited_separator as u8)
            .comment(self.delimited_comment.map(|c| c as u8))
            .quote(self.delimited_quote as u8)
            .escape(self.delimited_escape.map(|c| c as u8))
            .trim(self.delimited_trim)
            .from_reader(input_reader)
    }

    fn delimited_headers<R: std::io::Read>(
        &self,
        reader: &mut csv::Reader<R>,
    ) -> Result<Vec<String>, ShellError> {
        if self.table_no_headers {
            Ok((0..reader
                .headers()
                .map_err(|err| self.delimited_error(err))?
                .len())
                .map(|i| format!("column{i}"))
                .collect::<Vec<String>>())
        } else {
            Ok(reader
                .headers()
                .map_err(|err| self.delimited_error(err))?
                .iter()
                .map(String::from)
                .collect())
        }
    }

    fn delimited_row_value(
        &self,
        row: Result<csv::StringRecord, csv::Error>,
        headers: &[String],
    ) -> Value {
        let span = self.table_head;
        let row = match row {
            Ok(row) => row,
            Err(err) => return Value::error(self.delimited_error(err), span),
        };
        let columns = headers.iter().cloned();
        let values = row
            .into_iter()
            .map(|s| self.delimited_infer_value(s))
            .chain(std::iter::repeat(Value::nothing(span)));
        Value::record(columns.zip(values).collect(), span)
    }

    fn delimited_infer_value(&self, s: &str) -> Value {
        let span = self.table_head;
        if self.delimited_no_infer {
            Value::string(s, span)
        } else if let Ok(i) = s.parse() {
            Value::int(i, span)
        } else if let Ok(f) = s.parse() {
            Value::float(f, span)
        } else {
            Value::string(s, span)
        }
    }

    fn delimited_error(&self, err: csv::Error) -> ShellError {
        ShellError::DelimiterError {
            msg: err.to_string(),
            span: self.table_head,
        }
    }

    pub(crate) fn run_from_ssv(
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let name = call.head;
